import{_ as a,C as o,o as r,c as n,E as s,a2 as l}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"服务在线，不代表任务可以继续：OpenHands 的会话故障与 Agent 恢复边界","description":"","frontmatter":{"title":"服务在线，不代表任务可以继续：OpenHands 的会话故障与 Agent 恢复边界","date":"2026-08-26","column":"digital-employee","category":"daily","article_type":"case-study","edition":"research-center","research_question":"当服务仍然健康、会话或执行轮次仍存在时，运行时怎样证明当前任务仍有资格继续，并证明下游释放确实建立在已满足的上游依赖上？","summary":"从 OpenHands 一次 health 正常但会话失去活性的事故，到 CodeFlowMu 一条真实恢复链，区分服务健康、执行活性、任务资格、因果依赖与正式验收。","sources":"公开一手来源与访问受限的第一方证据范围均在正文列明。","project_relevance":"case-evidence","item_id":"EBR-20260826-04","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-26-service-health-task-recovery-case-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-08-26-service-health-task-recovery-case.md","filePath":"zh/digital-employee/2026-08-26-service-health-task-recovery-case.md","lastUpdated":1787803909000}'),i={name:"zh/digital-employee/2026-08-26-service-health-task-recovery-case.md"};function d(p,e,c,h,u,g){const t=o("ArticleCover");return r(),n("div",null,[s(t,{image:"/assets/covers/daily-2026-08-26-service-health-task-recovery-case-cover.png",kicker:"数字员工 · 工程研究",title:"服务在线，不代表任务可以继续：OpenHands 的会话故障与 Agent 恢复边界",summary:"健康只能说明服务还能回答；真正恢复还要重新证明任务可执行、依赖已满足，并把每一次继续与对应证据绑定。",version:"EBR-20260826-04",status:"工程研究 · 2026-08-26",languageHref:"/en/digital-employee/2026-08-26-service-health-task-recovery-case",languageLabel:"English"}),e[0]||(e[0]=l('<h1 id="服务在线-不代表任务可以继续-openhands-的会话故障与-agent-恢复边界" tabindex="-1">服务在线，不代表任务可以继续：OpenHands 的会话故障与 Agent 恢复边界 <a class="header-anchor" href="#服务在线-不代表任务可以继续-openhands-的会话故障与-agent-恢复边界" aria-label="Permalink to &quot;服务在线，不代表任务可以继续：OpenHands 的会话故障与 Agent 恢复边界&quot;">​</a></h1><p><strong>服务还能返回 200，只能说明某个接口仍然活着；它不能证明会话还在推进，更不能证明当前任务现在有资格继续。一次可靠的 Agent 恢复，真正需要重新证明的是：谁有权恢复、任务是否已经进入合法可执行状态、当前执行权是否仍有效，以及下游释放所依赖的上游事实是否真的成立。</strong></p><p>CodeFlowMu 是一个本地运行的多 Agent 协作系统，用任务、角色、门禁、报告与审批，把多个 Agent 的工作组织成可追踪、可恢复、可验证的执行链。我们在 2026-08-25 保留了一条真实恢复记录，它最后没有变成一个“系统成功自愈”的漂亮故事，因为其中留下了一个更有研究价值的问题：<strong>QA 的物理释放时间早于两份上游终态报告。</strong></p><p>这既不能直接证明门禁被绕过，也绝不能反过来证明依赖已经正确满足。它暴露的是另一件事：<strong>时间顺序不是因果证明。</strong></p><h2 id="_1-一盏绿灯-回答不了五个问题" tabindex="-1">1. 一盏绿灯，回答不了五个问题 <a class="header-anchor" href="#_1-一盏绿灯-回答不了五个问题" aria-label="Permalink to &quot;1. 一盏绿灯，回答不了五个问题&quot;">​</a></h2><p>Agent 系统发生故障时，经常会把几个完全不同的事实压成一个“正常 / 异常”状态。实际上至少需要分开看五层：</p><table tabindex="0"><thead><tr><th>层级</th><th>它真正回答什么</th><th>不能替代什么</th></tr></thead><tbody><tr><td>服务健康</td><td>进程或 API 还能不能响应？</td><td>会话是否还在推进</td></tr><tr><td>执行活性</td><td>当前 Session / job 是否仍有进展？</td><td>任务是否有资格继续</td></tr><tr><td>任务资格</td><td>当前任务是否处于合法、唯一、可派工状态？</td><td>上游依赖是否已经满足</td></tr><tr><td>因果依赖</td><td>为什么这个下游现在可以被释放？</td><td>业务结果是否验收通过</td></tr><tr><td>正式验收</td><td>当前交付是否被有权角色接受？</td><td>前面的技术事实</td></tr></tbody></table><p>所以真正的恢复链不是：</p><p><strong>服务在线 → 再叫醒 Agent</strong></p><p>而应该更接近：</p><p><strong>确认恢复授权 → 核对执行轮次与任务状态 → 证明依赖条件 → 再次派工 → 验证结果 → 正式验收</strong></p><p>这几层之间不能互相签字。</p><h2 id="_2-openhands-给出的外部参照-health-正常-会话仍可能已经失去活性" tabindex="-1">2. OpenHands 给出的外部参照：health 正常，会话仍可能已经失去活性 <a class="header-anchor" href="#_2-openhands-给出的外部参照-health-正常-会话仍可能已经失去活性" aria-label="Permalink to &quot;2. OpenHands 给出的外部参照：health 正常，会话仍可能已经失去活性&quot;">​</a></h2><p>OpenHands software-agent-sdk 的 PR #4548 记录了一次很具体的生产事故：浏览器工具相关的 conversation shutdown 卡住了约 <strong>8 小时 21 分</strong>，但 <code>/health</code> 和 metadata 路由仍然正常返回 200；conversation event 请求却无法正常打开。也就是说，从服务层看“还活着”，从具体会话看已经无法继续工作。</p><p>根因集中在 <code>AsyncExecutor.close()</code>：剩余任务没有被取消，portal thread 的等待又没有上限。修复一方面改为取消剩余任务，另一方面给关闭等待增加默认 <strong>10 秒</strong>边界；超时后记录 warning 并放弃继续无限等待。PR 还明确把这个行为定义成 <strong>bounded, best-effort safety net</strong>，而不是“所有资源已经保证清理完毕”。</p><p>这点非常重要，因为它没有用新的绿灯覆盖旧问题：</p><blockquote><p><strong>bounded shutdown 只是限制故障扩散，不等于证明会话已经干净退出。</strong></p></blockquote><p>OpenHands 这个案例只支持一个较窄的外部结论：<strong>service health ≠ session liveness。</strong> 它不是 CodeFlowMu 的根因，也不能替我们的任务恢复模型背书。</p><h2 id="_3-codeflowmu-的真实问题-agent-可以被唤醒-但任务还没合法进入执行态" tabindex="-1">3. CodeFlowMu 的真实问题：Agent 可以被唤醒，但任务还没合法进入执行态 <a class="header-anchor" href="#_3-codeflowmu-的真实问题-agent-可以被唤醒-但任务还没合法进入执行态" aria-label="Permalink to &quot;3. CodeFlowMu 的真实问题：Agent 可以被唤醒，但任务还没合法进入执行态&quot;">​</a></h2><p>CodeFlowMu 这次故障发生在更高一层。问题不是服务关闭，而是一条恢复路径可能在任务完成必要的生命周期迁移之前就唤醒 Worker。</p><p>这类故障危险的地方在于，它看起来很容易“修”：既然 Agent 停住了，再派一次就行。但如果任务还没有从待领取正确进入执行中，重新唤醒只会把不一致继续向下传播：新的 Session、报告、测试甚至完成状态，都可能建立在错误的任务前提上。</p><p>因此 ADMIN 给 PM 的恢复授权是有边界的：修复生命周期迁移、唤醒和报告门禁；增加回归证据；恢复或重派两项卡住的工作；并且在 <strong>DEV 与 OPS 的终态报告存在之前，不释放 QA</strong>。这不是一般性的“接管权限”，而是一份特定故障、特定动作范围内的恢复授权。</p><p>这也说明恢复的第一步不是技术动作，而是：</p><blockquote><p><strong>先证明谁有权修、允许修到哪里。</strong></p></blockquote><h2 id="_4-这条时间线最有价值的地方-是它没有替我们证明因果" tabindex="-1">4. 这条时间线最有价值的地方，是它没有替我们证明因果 <a class="header-anchor" href="#_4-这条时间线最有价值的地方-是它没有替我们证明因果" aria-label="Permalink to &quot;4. 这条时间线最有价值的地方，是它没有替我们证明因果&quot;">​</a></h2><p>公开 A4 时间线保留了几个关键节点：</p><table tabindex="0"><thead><tr><th>北京时间</th><th>事件</th></tr></thead><tbody><tr><td>14:35:22</td><td>有限恢复授权生效</td></tr><tr><td>14:35:29</td><td>恢复上下文投递给 PM</td></tr><tr><td>14:43:54</td><td>OPS 恢复派工</td></tr><tr><td>14:47:32</td><td>DEV 恢复派工</td></tr><tr><td>14:48:25</td><td>QA 从 inbox 进入 active</td></tr><tr><td>14:48:42</td><td>OPS 终态报告提交</td></tr><tr><td>14:49:37</td><td>DEV 终态报告提交</td></tr><tr><td>15:30:36</td><td>active-before-wake 修复提交并完成分组验证</td></tr></tbody></table><p>从物理时间看，QA 在 14:48:25 被释放，而两份上游终态报告分别在 17 秒和 72 秒之后出现。正式恢复指令又明确要求两份终态报告存在后才能释放 QA。</p><p>这里最容易犯两个相反的错误。</p><p>第一种是直接说：</p><blockquote><p>QA 一定被错误提前释放了。</p></blockquote><p>现有公开数据还不足以支持这么强的结论。写入时间、事件发生时间、时钟来源、是否存在未公开的先行逻辑事件，都可能不同。</p><p>第二种则是因为最后 OPS、DEV、QA 都进入终态，就说：</p><blockquote><p>依赖顺序已经被证明正确。</p></blockquote><p>这同样没有证据。</p><p>当前记录真正支持的是：</p><blockquote><p><strong>QA 释放所依赖的因果依据，没有在现有公开记录中被绑定得足够清楚。</strong></p></blockquote><p>这比一句“最终恢复成功”更有价值，因为它把下一阶段应该补什么说清楚了。</p><h2 id="_5-为什么时间戳不能单独承担依赖证明" tabindex="-1">5. 为什么时间戳不能单独承担依赖证明？ <a class="header-anchor" href="#_5-为什么时间戳不能单独承担依赖证明" aria-label="Permalink to &quot;5. 为什么时间戳不能单独承担依赖证明？&quot;">​</a></h2><p>分布式或多进程 Agent 系统里，物理时间很好用来排查问题，但它不是天然的因果凭据。至少存在几种不同时间：动作实际发生时间、事件写入时间、日志落盘时间、接口返回时间，以及不同进程自己的系统时钟。</p><p>因此，即使有：</p><p><strong>A.time &lt; B.time</strong></p><p>也不一定能推出：</p><p><strong>A 是 B 的已满足前置条件。</strong></p><p>真正可核查的下游释放应该更接近这样：</p><p><strong>QA release → prerequisite: OPS_REPORT#... + DEV_REPORT#... → required task revision → logical sequence / version precondition</strong></p><p>也就是说，释放记录本身要引用“是什么事实让我现在可以继续”。物理时间仍然保留用于诊断，但不再独自承担因果证明。</p><p>这和普通日志的区别很大。日志回答“后来发生了什么”；依赖证明回答“为什么这个动作在当时已经有资格发生”。</p><h2 id="_6-修复真正收紧的是-先激活-再唤醒" tabindex="-1">6. 修复真正收紧的是“先激活，再唤醒” <a class="header-anchor" href="#_6-修复真正收紧的是-先激活-再唤醒" aria-label="Permalink to &quot;6. 修复真正收紧的是“先激活，再唤醒”&quot;">​</a></h2><p>后续 Runtime 修复没有试图判断业务任务是否“成功”，而是把派工前的机械前提变得更严格：</p><ul><li>任务必须先完成合法生命周期激活，之后才能启动 Worker；</li><li>生命周期激活失败时 fail closed，不启动 TASK_BOUND Session，也不留下 active lease；</li><li>当前 attempt、执行权和负责 Agent 必须仍然匹配；</li><li>YAML / 文件状态回退路径也不能绕过生命周期判断；</li><li>PM 的主动恢复请求通过稳定的恢复 Skill / 路由进入，不把“发现故障”直接变成无限修复权。</li></ul><p>对应的修复验证被分开记录：生命周期治理 <strong>16 / 16</strong>、任务派工 <strong>46 / 46</strong>、YAML fallback <strong>4 / 4</strong>、PM core / routing <strong>7 / 7</strong>、恢复 Skill 路由 <strong>5 / 5</strong>，合计 78 个分组断言通过，Runtime TypeScript 类型检查无错误。</p><p>这些结果支持的是：<strong>被命名的 active-before-wake 修复路径已经通过对应回归。</strong> 它们不证明所有 Runtime 故障都能自动恢复，也没有自动补齐 QA 释放的历史因果证据。</p><h2 id="_7-一个更可靠的恢复合同应该长什么样" tabindex="-1">7. 一个更可靠的恢复合同应该长什么样？ <a class="header-anchor" href="#_7-一个更可靠的恢复合同应该长什么样" aria-label="Permalink to &quot;7. 一个更可靠的恢复合同应该长什么样？&quot;">​</a></h2><p>把这次事故抽象以后，一次高风险恢复至少需要经过以下链路：</p><p><strong>恢复授权 → attempt / lease reconciliation → lifecycle activation → prerequisite binding → worker wake → execution evidence → formal acceptance</strong></p><p>其中任何一层都不能跳级：</p><ul><li>health 只能证明服务还能回答；</li><li>heartbeat / progress 只能证明执行活性；</li><li>lifecycle activation 才证明任务允许进入执行；</li><li>prerequisite binding 才证明下游为什么现在可释放；</li><li>REPORT / test 只能形成交付证据；</li><li>REVIEW / ADMIN 才形成正式业务结论。</li></ul><p>所以恢复系统真正应该追求的不是“更快把 Agent 叫回来”，而是让每一次继续都能回答：</p><blockquote><p><strong>谁授权了这次恢复？当前任务为什么已经有资格执行？它依赖的上游事实是哪几个？这些事实对应哪个版本？最终又由谁确认交付成立？</strong></p></blockquote><h2 id="结论-恢复不是重新启动-而是重新建立资格" tabindex="-1">结论：恢复不是重新启动，而是重新建立资格 <a class="header-anchor" href="#结论-恢复不是重新启动-而是重新建立资格" aria-label="Permalink to &quot;结论：恢复不是重新启动，而是重新建立资格&quot;">​</a></h2><p>OpenHands 的事故提醒我们：<strong>健康信号不能替会话活性签字。</strong> CodeFlowMu 的恢复案例进一步提醒：<strong>会话活着也不能替任务资格和依赖条件签字。</strong></p><p>真正可靠的 Agent Runtime，需要把“还能回答”“还在运行”“允许继续”“依赖已满足”“可以交付”拆成不同事实，并让它们通过明确的证据关系连接起来。</p><p>这次案例最后没有给我们一个完美的“全部正确”结论。相反，它留下了一个更重要的工程缺口：QA 的释放在物理时间上早于两份上游报告，而现有记录不足以证明真正的因果顺序。</p><p>这正是工程证据应该做的事：不是替系统补一个漂亮解释，而是告诉我们下一步还缺什么。</p><blockquote><p><strong>服务在线，不代表任务可以继续；任务恢复，也必须重新证明为什么现在可以继续。</strong></p></blockquote><hr><h2 id="公开证据" tabindex="-1">公开证据 <a class="header-anchor" href="#公开证据" aria-label="Permalink to &quot;公开证据&quot;">​</a></h2><ul><li><a href="/joinwell52/evidence/execution-boundary-20260826/v2/case-a4-recovery-timeline.csv"><strong>查看 A4 授权、恢复与验证时间线（CSV）</strong></a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/execution-boundary-20260826/v2/transcript-a4.md" target="_blank" rel="noreferrer"><strong>查看 A4 脱敏审计与回归摘录（GitHub）</strong></a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/execution-boundary-20260826/v2/claim-evidence-map.csv" target="_blank" rel="noreferrer"><strong>核对本文主张对应哪一条证据（GitHub）</strong></a></li><li><a href="/joinwell52/zh/digital-employee/2026-08-26-execution-boundary-evidence-data"><strong>查看公开、脱敏的 Execution Boundary 四案例数据包</strong></a></li></ul><h2 id="来源与证据边界" tabindex="-1">来源与证据边界 <a class="header-anchor" href="#来源与证据边界" aria-label="Permalink to &quot;来源与证据边界&quot;">​</a></h2><h3 id="openhands" tabindex="-1">OpenHands <a class="header-anchor" href="#openhands" aria-label="Permalink to &quot;OpenHands&quot;">​</a></h3><ul><li><a href="https://github.com/OpenHands/software-agent-sdk/pull/4548" target="_blank" rel="noreferrer"><strong>OpenHands software-agent-sdk PR #4548 — bound <code>AsyncExecutor.close()</code></strong></a>，2026-08-25 合并。本文引用其“health / metadata 仍正常，但 conversation shutdown 与 events 路径长时间失去活性”的事故，以及取消剩余任务、默认 10 秒有界关闭、超时后 best-effort abandonment 的修复。8 小时 21 分等事故数据来自 PR 作者报告，本文未独立复现。</li></ul><p>OpenHands 案例只用于支持 <strong>service health ≠ session liveness</strong>。本文不把它视为 CodeFlowMu 的根因，也不据此声称 OpenHands 的恢复机制与 CodeFlowMu 的任务治理等价。</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>本文关于 CodeFlowMu 的公开结论只适用于 A4 证据覆盖的 2026-08-25 有限恢复案例和命名回归路径。公开记录支持：恢复授权有明确范围；任务恢复确实发生；active-before-wake 修复的生命周期、派工、fallback、PM routing 与 recovery skill 分组验证通过；同时 QA 的物理释放时间早于两份上游终态报告。</p><p>这些证据<strong>不能证明</strong> QA 一定发生了门禁违规，也不能证明该释放已经满足因果前置条件；更不能推出所有 Runtime 故障都能沿同一路径恢复。完整 Session、Agent transcript、聊天和本机路径不公开。</p><p>研究结论应始终与对应版本、测试集合和证据边界一起阅读。</p>',77))])}const v=a(i,[["render",d]]);export{m as __pageData,v as default};
